from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NEW_YORK)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        equity = self.AddEquity("SPY", Resolution.MINUTE)
        equity.SetDataNormalizationMode(DataNormalizationMode.RAW)
        equity.SetFillDataForward(False)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.MINUTE)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=90))
        )
        self.option_symbol = option.Symbol

        self._five_minute_closes = deque(maxlen=20)
        self._previous_fast = None
        self._previous_slow = None

        self._active_bar_end = None
        self._active_bar_count = 0
        self._active_bar_close = None

        self._held_contract = None
        self._entry_order_id = None
        self._exit_order_id = None
        self._entry_fill_price = None
        self._time_stop_date = None
        self._no_entry_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        if self._held_contract is not None:
            if self.Time.date() >= self._held_contract.ID.Date.date():
                self._no_entry_date = self.Time.date()
                self._submit_exit("expiration safeguard")
            else:
                self._evaluate_exit(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_spy_minute_bar(spy_bar, data)

    def _process_spy_minute_bar(self, bar: TradeBar, data: Slice):
        end_time = bar.EndTime.replace(second=0, microsecond=0)
        minutes_to_boundary = (5 - (end_time.minute % 5)) % 5
        bar_end = end_time + timedelta(minutes=minutes_to_boundary)

        session_start = time(9, 35)
        session_end = time(16, 0)
        if not (session_start <= bar_end.time() <= session_end):
            self._discard_active_bar()
            return

        if self._active_bar_end is None:
            self._start_active_bar(bar_end, bar.Close)
        elif bar_end != self._active_bar_end:
            self._finalize_active_bar(data)
            self._start_active_bar(bar_end, bar.Close)
        else:
            self._active_bar_count += 1
            self._active_bar_close = bar.Close

        if end_time == bar_end:
            self._finalize_active_bar(data)

    def _start_active_bar(self, bar_end, close):
        self._active_bar_end = bar_end
        self._active_bar_count = 1
        self._active_bar_close = close

    def _discard_active_bar(self):
        self._active_bar_end = None
        self._active_bar_count = 0
        self._active_bar_close = None

    def _finalize_active_bar(self, data: Slice):
        if self._active_bar_end is None:
            return

        bar_end = self._active_bar_end
        count = self._active_bar_count
        close = self._active_bar_close
        self._discard_active_bar()

        if count != 5:
            return

        self._five_minute_closes.append(close)
        if len(self._five_minute_closes) < 20:
            return

        closes = list(self._five_minute_closes)
        fast = sum(closes[-5:]) / 5
        slow = sum(closes) / 20

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        if (
            bullish_cross
            and time(9, 45) <= bar_end.time() <= time(14, 30)
        ):
            self._try_enter(data, close)

    def _try_enter(self, data: Slice, spy_price):
        if self._held_contract is not None or self._entry_order_id is not None:
            return

        if self._no_entry_date == self.Time.date():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Right == OptionRight.CALL
                and contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expirations:
            self.Debug("Entry skipped: no expiry at least 7 calendar days out")
            return

        expiry = expirations[0]
        minimum_strike = spy_price * 1.01
        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.CALL
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} expiry {expiry} strike {selected.Strike}"
        )

    def _evaluate_exit(self, data: Slice):
        if self._exit_order_id is not None:
            return

        if self._time_stop_date == self.Time.date() and self.Time.time() >= time(15, 45):
            self._submit_exit("pre-expiration time stop")
            return

        bid = 0
        ask = 0
        for chain in data.OptionChains.values():
            for contract in chain:
                if contract.Symbol == self._held_contract:
                    bid = contract.BidPrice
                    ask = contract.AskPrice
                    break
            if bid > 0 and ask > 0:
                break

        if bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2
            if midpoint >= self._entry_fill_price * 1.50:
                self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self._held_contract is None or self._exit_order_id is not None:
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self._held_contract):
            self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self._held_contract, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason} for {self._held_contract}")

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        if any(
            order.Symbol == self.spy
            for order in self.Transactions.GetOpenOrders(self.spy)
        ):
            return

        self.Debug("Unexpected SPY exercise/assignment position; liquidating")
        self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.FILLED:
                self._held_contract = order_event.Symbol
                self._entry_fill_price = order_event.FillPrice
                self._entry_order_id = None
                self._exit_order_id = None

                hours = self.Securities[self._held_contract].Exchange.Hours
                self._time_stop_date = hours.GetPreviousTradingDay(
                    self._held_contract.ID.Date
                ).date()

                self.Debug(
                    f"Entry filled: {self._held_contract} at {self._entry_fill_price}"
                )
            elif order_event.Status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
            ):
                self._entry_order_id = None

        elif order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.FILLED:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}"
                )
                self._held_contract = None
                self._entry_fill_price = None
                self._time_stop_date = None
                self._exit_order_id = None
            elif order_event.Status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
            ):
                self._exit_order_id = None

