            return

        if self._held_contract is not None or self._entry_order_is_open():
            return

        if self.spy not in data.Bars:
            self.Debug("Entry skipped: SPY has no current minute bar.")
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Entry skipped: no option chain in the current Slice.")
            return

        spot = data.Bars[self.spy].Close
        minimum_expiry = self.Time.date() + timedelta(days=7)
        chain = data.OptionChains[self.option_symbol]

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

