        if self._held_contract is None:
            return

        if self.Time.time() != time(15, 45):
            return

        expiry = self._held_contract.ID.Date.date()
        next_open = self.Securities[self.spy].Exchange.Hours.GetNextMarketOpen(
            self.Time, False
        )

        if next_open.date() == expiry:
            self._submit_exit("15:45 pre-expiration time stop")

    def _handle_expiration_safety(self):
        if self._held_contract is None:
            return

        expiry = self._held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self._blocked_entry_date = self.Time.date()
            self._submit_exit("expiration safety liquidation", replace_open_exit=True)

    def _submit_exit(self, reason, replace_open_exit=False):
        if self._held_contract is None:
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity == 0:
            return

        if self._exit_order_is_open() and not replace_open_exit:
            return

        if self._exit_order_is_open():
            self.Transactions.CancelOpenOrders(self._held_contract)

        ticket = self.MarketOrder(self._held_contract, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self._held_contract}")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if any(order.Symbol == self.spy for order in self.Transactions.GetOpenOrders()):
            return

        self.MarketOrder(self.spy, -quantity)
        self.Debug(
            f"Unexpected SPY exercise/assignment position detected; "
            f"submitted liquidation for {quantity} shares."
        )

    def _entry_order_is_open(self):
        if self._entry_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self._entry_order_id)
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _exit_order_is_open(self):
        if self._exit_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self._exit_order_id)
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self._entry_order_id:
            if order_event.FillQuantity > 0:
                self._held_contract = self._entry_contract
                self._entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self._held_contract} at {self._entry_price}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_order_id = None
                if self._held_contract is None:
                    self._entry_contract = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self._held_contract} at {order_event.FillPrice}")
                self._held_contract = None
                self._entry_price = None
                self._exit_order_id = None
                self._entry_contract = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._exit_order_id = None

