        self.expiration_block_date = None

    def OnData(self, data):
        self.current_slice = data

        if self.spy in data.Bars:
            self.consolidator.Update(data.Bars[self.spy])

        if self.Portfolio[self.spy].Invested:
            self.HandleUnexpectedEquityPosition()
            return

        if self.held_option is None:
            return

        if not self.Portfolio[self.held_option].Invested:
            return

        expiry_date = self.DateOnly(self.held_option.ID.Date)
        today = self.Time.date()

        if today >= expiry_date:
            self.expiration_block_date = today
            self.SubmitOptionExit("expiration safety exit")
            return

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            datetime(expiry_date.year, expiry_date.month, expiry_date.day)
        )

        if today == previous_trading_day.date() and self.Time.hour == 15 and self.Time.minute == 45:
            self.SubmitOptionExit("pre-expiration time stop")
            return

        if self.entry_price is None or self.exit_order_id is not None:
            return

        if self.held_option not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_option]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitOptionExit("50% profit target")

    def OnFiveMinuteBar(self, sender, bar):
        self.close_window.Add(float(bar.Close))

        if not self.close_window.IsReady:
            return

        fast = sum(self.close_window[i] for i in range(5)) / 5.0
        slow = sum(self.close_window[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (bar.EndTime.hour > 9 or (bar.EndTime.hour == 9 and bar.EndTime.minute >= 45)):
            return
        if not (bar.EndTime.hour < 14 or (bar.EndTime.hour == 14 and bar.EndTime.minute <= 30)):
            return

        self.TryEnterCall()

    def TryEnterCall(self):
        if self.current_slice is None:
            return

        if self.expiration_block_date == self.Time.date():
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if self.Portfolio[self.spy].Invested:
            return

        if self.option_symbol not in self.current_slice.OptionChains:
            self.Debug("Entry skipped: no SPY option chain in Slice.")
            return

        chain = self.current_slice.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            self.DateOnly(contract.Expiry)
            for contract in chain
            if self.DateOnly(contract.Expiry) >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Entry skipped: no expiration at least seven calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        spot = self.Securities[self.spy].Price
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and self.DateOnly(contract.Expiry) == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1, tag="Five-minute bullish crossover call entry")
        self.entry_order_id = ticket.OrderId
        self.held_option = selected.Symbol
        self.entry_price = None
        self.Debug("Entry submitted: {0}".format(selected.Symbol))

    def SubmitOptionExit(self, reason):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        if self.exit_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
            if ticket is not None and ticket.Status not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_option, -quantity, tag=reason)
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted: {0} ({1})".format(self.held_option, reason))

    def HandleUnexpectedEquityPosition(self):
        if self.equity_exit_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.equity_exit_order_id)
            if ticket is not None and ticket.Status not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.spy, -quantity, tag="Unexpected option exercise or assignment")
        self.equity_exit_order_id = ticket.OrderId
        self.Debug("Unexpected SPY exercise/assignment position: liquidating SPY.")

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self.entry_order_id:
            if orderEvent.Status == OrderStatus.Filled and orderEvent.FillQuantity > 0:
                self.entry_price = float(orderEvent.FillPrice)
                self.Debug("Entry filled: {0} at {1}".format(orderEvent.Symbol, self.entry_price))
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None
                self.held_option = None
                self.entry_price = None

        if orderEvent.OrderId == self.exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0} at {1}".format(orderEvent.Symbol, orderEvent.FillPrice))
                self.exit_order_id = None
                self.entry_order_id = None
                self.held_option = None
                self.entry_price = None
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

        if orderEvent.OrderId == self.equity_exit_order_id:
            if orderEvent.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self.equity_exit_order_id = None

    def DateOnly(self, value):
        try:
            return value.date()
        except AttributeError:
            return date(value.Year, value.Month, value.Day)

